    let cv = C.text.get(key);
    if (!cv) {
      const m = H.layer(4, 4).getContext('2d'); m.font = `${font} ${size}px "Caveat"`;
      const w = Math.ceil(m.measureText(str).width) + 30, h = Math.ceil(size * 1.5);
