      tc.globalAlpha = 0.85; tc.fillText(str, 15, size * 1.08); tc.globalAlpha = 0.25; tc.fillText(str, 16.5, size * 1.08 + 1);
      rimPool(cv, 2.4, 2.5);
      cv.base = size * 1.08;
