  };

  // ---------- faces: flat printed pieces of card in their own 2D frame ----------
  let GID = 1;
  const mkF = (O, ex, ey, poly, o) => {
    let pw = 0, ph = 0;
    for (const p of poly) { pw = Math.max(pw, p[0]); ph = Math.max(ph, p[1]); }
