  const flat = (w, d, col, print, y = 0.06) => [mkF([-w / 2, y, d / 2], [1, 0, 0], [0, 0, -1], rect(w, d), { grp: GID++, col, print, flat: true })];
  // prism along an axis frame {o, ax, u, v}; sec is a CCW 2D section in (u, v)
