    c.fillStyle = PAL.pink; c.beginPath(); c.moveTo(x - s * 0.05, y + s * 0.13); c.lineTo(x + s * 0.05, y + s * 0.13); c.lineTo(x, y + s * 0.19); c.fill();
    c.strokeStyle = PAL.ink; c.lineWidth = s * 0.018;
