  // ---- prints for each piece ----
  const pCardFace = (kind) => (c, w, h) => {
    c.fillStyle = PAL.card; c.fillRect(0, 0, w, h);
    c.fillStyle = kind === 'cat' ? '#bcd9ee' : '#f5d898'; rr(c, 3.5, 3.5, w - 7, h * 0.6, 2.5); c.fill();
