      };
      // card scraping across the mat
      const scrape = (t, d, g = 1, p = 0) => k.noise(t, { dur: d, filter: 'bandpass', f: [[0, 1100], [d, 1500]], q: 0.8, gain: 0.07 * g, a: d * 0.3, hold: d * 0.3, pan: p, minor: true });
      // the camera sliding across the mat: a smooth low air move, no rustle
      const glide = (t, d, g = 1) => k.noise(t, { dur: d, color: 'brown', filter: 'lowpass', f: [[0, 200], [d * 0.5, 380], [d, 200]], gain: 0.1 * g, a: d * 0.5 });
      const snip = (t, g = 1, p = 0) => { // craft-knife / scissor snip for small parts
        k.noise(t, { dur: 0.012, filter: 'highpass', f: 3200, gain: 0.2 * g, a: 0.001, pan: p, minor: true });
        k.noise(t + 0.006, { dur: 0.03, filter: 'bandpass', f: 1900, q: 3, gain: 0.12 * g, a: 0.001, pan: p, minor: true });
      };
      const flick = (t, g = 1, p = 0) => { // a printed number card flicked over
        k.noise(t, { dur: 0.02, filter: 'bandpass', f: 1700, q: 1.6, gain: 0.24 * g, a: 0.001, pan: p, minor: true });
        k.tone(t, { f: 210, dur: 0.03, gain: 0.04 * g, pan: p, minor: true });
      };
      // a whole box folding up from its net (fold progress f(t) = eio(win(t, a, b)))
      const boxFold = (a, b, x, g = 1, tabs = true) => {
        const at = (f) => S(a + (b - a) * inv(f));
        bend(S(a), at(0.62), 0.9 * g, pan(x, a));
        [0.62, 0.71, 0.8, 0.89].forEach((f, i) => crease(at(f), (0.7 + 0.1 * i) * g, pan(x, at(f))));
        if (tabs) tab(at(0.95), 0.9 * g, pan(x, b));
      };
      const tentFold = (a, b, x, g = 1, minor = true) => { bend(S(a), S(b), g, pan(x, a)); crease(S(b), g, pan(x, b), minor); };
      const stripRun = (path, a, b, x, g = 1) => { // strip arrow unrolling: a crease at each accordion fold as it extends
        const L = pathLen(resample(path));
        scrape(S(a), b - a, 0.9 * g, pan(x, a));
        let last = -1;
        for (let l = 3; l < L - 3; l += 3) { const tt = S(a + (b - a) * inv(l / L)); if (tt - last >= 1 / 12) { crease(tt, 0.32 * g, pan(x, tt)); last = tt; } }
        crease(S(b), 0.6 * g, pan(x, b));
      };
      const land = (t0, x, g = 1) => tap(S(t0 + XT.DROP), g, pan(x, t0 + XT.DROP));

      k.bed('room', 0, 15, { gain: 0.45 });

      // 1 HOOK: the template is smoothed flat, then folds up into the question card
      k.noise(0.0, { dur: 0.45, color: 'pink', filter: 'bandpass', f: [[0, 500], [0.45, 800]], q: 0.6, gain: 0.09, a: 0.15, pan: -0.1, minor: true });
      tentFold(XT.qFold[0], XT.qFold[1], -6, 1.4, false);
      tap(S(XT.qFold[1]) + 0.02, 1.3, 0, false); // the question card's feet settle on the mat
      k.tone(S(XT.qFold[1]) + 0.03, { f: 'G3', type: 'triangle', dur: 0.3, gain: 0.1, filter: 'lowpass', f2: 900 });
      glide(XT.slide1[0], XT.slide1[1] - XT.slide1[0]);

      // 2 DATA: robot body and head fold up, examples are set down and tagged
      boxFold(XT.body[0], XT.body[1], ROBOT.x, 1.1);
      boxFold(XT.head[0], XT.head[1], ROBOT.x + 17, 0.8);
      land(XT.catDrop, 21, 0.9); land(XT.dogDrop, 29, 0.9);
      land(XT.catTag, 22, 0.6); land(XT.dogTag, 37, 0.6);
      k.noise(S(XT.hop[0]), { dur: XT.hop[1] - XT.hop[0], color: 'pink', filter: 'bandpass', f: [[0, 400], [0.18, 700], [0.35, 400]], q: 0.7, gain: 0.07, a: 0.15, pan: pan(ROBOT.x + 8, XT.hop[0]), minor: true });
      tap(S(XT.hop[1]), 1.1, pan(ROBOT.x, XT.hop[1]), false); tab(S(XT.hop[1]) + 0.05, 1, pan(ROBOT.x, XT.hop[1])); // head pressed onto the body
      snip(S(XT.parts[0]), 0.9, pan(ROBOT.x, 3.9)); snip(S(XT.parts[0]) + 0.09, 0.8, pan(ROBOT.x, 3.95)); tap(S(XT.parts[0] + 0.12), 0.5, pan(ROBOT.x, 4));
      stripRun(ARROW1, XT.arrow1[0], XT.arrow1[1], 47);
      tentFold(XT.ctr[0], XT.ctr[1], 47, 0.9);
      { // counter: every printed number change is a card flick, thinning out toward the end
        let last = -1;
        for (let f = Math.ceil(XT.count[0] * 12) + 1; f < XT.count[1] * 12; f++) { const t = f / 12; if (t - last >= (t < 5.1 ? 1 / 12 : 1 / 6)) { flick(t, 0.8, pan(47, t)); last = t; } }
        crease(S(XT.count[1]), 0.9, pan(47, XT.count[1]), false); // 1,000,000 settles
      }
      for (let i = 0; i < XT.nCards; i++) { // cards slide along the strip and drop through the DATA IN slot
        const a = XT.cards0 + i * XT.cardGap, b = a + XT.cardDur;
        if (i % 2 === 0) scrape(S(a), XT.cardDur, 0.6, pan(40, a));
        k.noise(S(b), { dur: 0.05, color: 'brown', filter: 'lowpass', f: 520, gain: 0.22, a: 0.002, pan: pan(ROBOT.x, b), minor: true });
      }

      // 3 GUESS -> CHECK -> ADJUST
      glide(XT.slide2[0], XT.slide2[1] - XT.slide2[0]);
      bend(S(XT.ctrDown[0]), S(XT.ctrDown[1]), 0.6, pan(44, 6.2)); tap(S(XT.ctrDown[1]), 0.5, pan(44, 6.4)); // counter card laid flat
      scrape(S(XT.ctrAway[0]), XT.ctrAway[1] - XT.ctrAway[0], 1.1, -0.6); // ...and slid off to the side
      land(XT.newCard, 61, 0.8);
      k.noise(S(XT.look), { dur: 0.12, filter: 'bandpass', f: 800, q: 1.2, gain: 0.08, a: 0.04, pan: pan(ROBOT.x, XT.look), minor: true }); // head turns on its tab
      stripRun(GUESS, XT.guessArrow[0], XT.guessArrow[1], 86, 0.8);
      land(XT.guessTag, 85, 0.6);
      tentFold(XT.ans[0], XT.ans[1], 101, 1.1, false);
      glide(XT.push[0], XT.push[1] - XT.push[0], 1.2);
      // the wrong guess: the red flag is jabbed into its block with a firm desk thump
      const tX = S(XT.xPop[0] + 0.12);
      k.noise(S(XT.xPop[0]), { dur: 0.08, color: 'pink', filter: 'bandpass', f: [[0, 700], [0.08, 1500]], q: 0.7, gain: 0.16, a: 0.03, pan: pan(114, 8) });
      k.play('thud', tX, { f: 110, gain: 0.85, pan: pan(114, tX) });
      k.play('slap', tX + 0.01, { gain: 0.35, pan: pan(114, tX) });
      k.tone(tX + 0.03, { f: 'D3', type: 'triangle', dur: 0.18, gain: 0.16, filter: 'lowpass', f2: 700 });
      k.tone(tX + 0.2, { f: 'A2', type: 'triangle', dur: 0.36, gain: 0.18, filter: 'lowpass', f2: 600 });
      land(XT.checkTag, 116, 0.6);
      stripRun(ADJ, XT.adjArrow[0], XT.adjArrow[1], 92, 0.9);
      land(XT.adjTag, 91, 0.6);
      scrape(S(XT.token[0]), XT.token[1] - XT.token[0], 1.4, pan(92, 8.8)); // the error chip sliding back along the strip
      for (let f = Math.ceil(XT.dials[0] * 12); f <= XT.dials[1] * 12; f++) { // paper dials turning on split pins
        const t = f / 12; k.noise(t, { dur: 0.018, filter: 'bandpass', f: 1300 + (f % 3) * 200, q: 2.2, gain: 0.22, a: 0.001, pan: pan(ROBOT.x, t), minor: true });
        k.tone(t, { f: 180, dur: 0.03, gain: 0.05, pan: pan(ROBOT.x, t), minor: true });
      }
      // answer card and flag spin round to the right answer
      k.noise(S(XT.spin[0]), { dur: 0.4, color: 'pink', filter: 'bandpass', f: [[0, 420], [0.2, 950], [0.4, 450]], q: 0.7, gain: 0.14, a: 0.18, pan: pan(106, 9.7) });
      crease(S(XT.spin[1]), 1.1, pan(103, 10), false);
      k.play('success', S(XT.spin[1]) + 0.01, { f: 'G5', gain: 0.22, pan: pan(103, 10) });

      // 4 PROGRESS: bars fold up one by one, the score card counts
      glide(XT.slide3[0], XT.slide3[1] - XT.slide3[0]);
      tap(S(XT.bar0 - 0.3), 0.7, pan(168, 10.8)); // chart base card laid down
      tentFold(XT.acc[0], XT.acc[1], 198, 0.9); tentFold(XT.acc[0], XT.acc[1], 168, 0.6);
      XT.ACCS.forEach((a, i) => { const t0 = XT.bar0 + i * XT.barGap; boxFold(t0, t0 + XT.barDur, 153 + i * 6.2, 0.55, false); });
      { // shown % changes -> card flicks (<= 12/s)
        let lastV = -1, lastT = -1;
        for (let f = Math.ceil(XT.acc[0] * 12); f < Math.round(XT.hit * 12); f++) {
          const q = f / 12; let v = XT.ACCS[0];
          XT.ACCS.forEach((a, i) => { const t0 = XT.bar0 + i * XT.barGap, ff = eio(win(q, t0, t0 + XT.barDur)); if (q >= t0 && ff > 0.5) v = Math.max(v, lerp(i ? XT.ACCS[i - 1] : 55, a, win(ff, 0.5, 1))); });
          v = Math.round(v); if (v !== lastV && q - lastT >= 1 / 12) { flick(q, 0.75, pan(198, q)); lastV = v; lastT = q; }
        }
      }
      // 97%: firm desk thump as the score turns green and the paper star springs open (biggest hit)
      const tH = S(XT.hit);
      glide(12.45, 0.4, 1.1);
      k.play('impact', tH, { gain: 1.25, pan: 0.15 });
      k.play('ding', tH + 0.01, { f: 'E5', gain: 0.55, pan: 0.25 });
      k.noise(tH, { dur: 0.16, color: 'pink', filter: 'bandpass', f: [[0, 800], [0.16, 2000]], q: 0.6, gain: 0.2, a: 0.02, pan: 0.35 });
      crease(S(XT.star[1]), 0.8, 0.35);

      // 5 TAKEAWAY: the banner folds up in front and the lesson resolves
      tentFold(XT.banner[0], XT.banner[1], 172, 1.4, false);
      tap(S(XT.banner[1]) + 0.02, 1.0, 0, false);
      ['C4', 'G4', 'E5'].forEach((f, i) => k.play('ding', S(XT.banner[1]) + 0.16 + i * 0.1, { f, gain: [0.38, 0.32, 0.44][i], pan: (i - 1) * 0.25 }));
    },
  });
}

film-noir.source:
{
  // ---------- 1940s film noir still ----------
  const BAR = 54;

  function detectivePath(x) {
    // standing figure facing left; fedora, profile, turned-up collar, trench coat
    x.beginPath();
    x.moveTo(700, 720);
    x.bezierCurveTo(706, 560, 716, 470, 742, 420);   // coat front (left) edge
    x.bezierCurveTo(756, 392, 770, 372, 778, 352);   // lapel to collar
    x.lineTo(770, 334);                               // collar point
    x.bezierCurveTo(772, 322, 776, 312, 780, 304);   // chin underside
    x.lineTo(772, 300); x.lineTo(770, 292);           // chin
    x.lineTo(764, 284); x.lineTo(766, 276);           // lips
    x.lineTo(758, 264); x.lineTo(764, 258);           // nose tip -> under nose
    x.bezierCurveTo(766, 248, 770, 240, 772, 232);   // brow
    x.lineTo(730, 226);                               // hat brim front (tilted down)
    x.bezierCurveTo(728, 220, 740, 214, 772, 212);
    x.bezierCurveTo(776, 190, 786, 168, 812, 160);   // crown front
    x.bezierCurveTo(828, 156, 848, 160, 862, 158);   // pinch
    x.bezierCurveTo(880, 164, 888, 190, 890, 206);
    x.bezierCurveTo(912, 208, 934, 214, 938, 222);   // brim back
    x.bezierCurveTo(918, 230, 896, 230, 880, 230);
    x.bezierCurveTo(878, 260, 872, 290, 868, 306);   // back of head / neck
    x.bezierCurveTo(886, 318, 900, 322, 910, 330);   // collar back
    x.bezierCurveTo(960, 344, 1000, 366, 1018, 410); // shoulder
    x.bezierCurveTo(1036, 470, 1044, 580, 1050, 720);
    x.closePath();
  }
  function armPath(x) {
    // forearm raised, hand holding cigarette near chest
    x.beginPath();
    x.moveTo(820, 470);
    x.bezierCurveTo(790, 480, 760, 476, 735, 462);
    x.bezierCurveTo(720, 456, 712, 446, 716, 436);
    x.bezierCurveTo(722, 428, 736, 430, 746, 436);
    x.bezierCurveTo(770, 446, 800, 444, 830, 432);
    x.closePath();
  }

  // ================= EXPLAINER: a 1940s newsreel / B-picture montage =================
  let corkTex = null;
  function getCork(W, Hh) {
    if (corkTex) return corkTex;
    const c = H.layer(W, Hh), x = c.getContext('2d'), img = x.createImageData(W, Hh), d = img.data, R = H.rng(1212), nz = H.makeNoise(1213);
    for (let y = 0; y < Hh; y++) for (let xx = 0; xx < W; xx++) {
      const v = 112 + nz.n2(xx * 0.02, y * 0.02) * 16 + (R() - 0.5) * 46 + (R() < 0.04 ? -40 : 0);
      const i = (y * W + xx) * 4; d[i] = d[i + 1] = d[i + 2] = v; d[i + 3] = 255;
    }
    x.putImageData(img, 0, 0); return (corkTex = c);
  }
  const gy = (v, a = 1) => `rgba(${v},${v},${v},${a})`;
  // painted plaster (mean ~128, used through 'overlay' so it adds material without shifting exposure); half-res, cached
  let plasterTex = null, hazeTex = null;
  function getPlaster(W, Hh) {
    if (plasterTex && plasterTex.width === W && plasterTex.height === Hh) return plasterTex;
    const w = W >> 1, h = Hh >> 1, s = H.layer(w, h), x = s.getContext('2d'), img = x.createImageData(w, h), d = img.data, R = H.rng(1331), nz = H.makeNoise(1332);
    for (let y = 0; y < h; y++) for (let xx = 0; xx < w; xx++) {
      const v = 128 + nz.fbm2(xx * 0.018, y * 0.018, 3) * 30 + nz.n2(xx * 0.16, y * 0.16) * 8 + (R() - 0.5) * 12;
      const i = (y * w + xx) * 4; d[i] = d[i + 1] = d[i + 2] = v; d[i + 3] = 255;
    }
    x.putImageData(img, 0, 0);
    const c = H.layer(W, Hh); c.getContext('2d').drawImage(s, 0, 0, W, Hh); return (plasterTex = c);
  }
  // hanging cigarette-smoke strata (white, alpha = density); half-res, cached
  function getHaze(W, Hh) {
    if (hazeTex && hazeTex.width === (W >> 1) && hazeTex.height === (Hh >> 1)) return hazeTex;
    const w = W >> 1, h = Hh >> 1, s = H.layer(w, h), x = s.getContext('2d'), img = x.createImageData(w, h), d = img.data, nz = H.makeNoise(1414);
    for (let y = 0; y < h; y++) for (let xx = 0; xx < w; xx++) {
      const q = nz.n2(xx * 0.004, y * 0.01) * 1.6;
      const v = nz.fbm2(xx * 0.007 + q, y * 0.02, 4);
      const i = (y * w + xx) * 4; d[i] = d[i + 1] = d[i + 2] = 255; d[i + 3] = H.clamp((v + 0.15) * 1.5) * 255;
    }
    x.putImageData(img, 0, 0); return (hazeTex = s);
  }
  // venetian-blind light: same slat geometry as before (34 px period, 17 px gaps, slope 0.5), drawn at half res with a
  // real penumbra blur, a soft window-frame edge and an optional mullion shadow. bg/color allow a multiply shadow pass.
  function slats(W, Hh, o) {
    const w = W >> 1, h = Hh >> 1, l = H.layer(w, h), x = l.getContext('2d');
    const x0 = o.x0, sw = o.sway || 0, X1 = W + 200, dy = (X1 - x0) * 0.5;
    if (o.bg) { x.fillStyle = o.bg; x.fillRect(0, 0, w, h); }
    x.save(); x.filter = `blur(${(o.blur || 3) / 2}px)`; x.scale(0.5, 0.5); x.globalAlpha = o.alpha; x.fillStyle = o.color || '#fff';
    x.beginPath();
    for (let k = -10; k < 48; k++) { const y = k * 34 + sw; x.moveTo(x0, y); x.lineTo(X1, y - dy); x.lineTo(X1, y - dy + 17); x.lineTo(x0, y + 17); x.closePath(); }
    x.fill();
    if (o.mullion) { const [mx, ms] = o.mullion; x.globalAlpha = o.bg ? Math.min(1, o.alpha * 1.4) : 1; x.globalCompositeOperation = o.bg ? 'source-over' : 'destination-out'; x.strokeStyle = o.bg ? (o.color || '#000') : '#000'; x.lineWidth = 9;
      x.beginPath(); x.moveTo(mx - 60 * ms, -60); x.lineTo(mx + (Hh + 60) * ms, Hh + 60); x.stroke(); }
    x.restore();
    if (!o.bg && o.edge) { // window-frame penumbra on the leading edge, light strongest deep in the patch
      x.save(); x.globalCompositeOperation = 'destination-in'; x.scale(0.5, 0.5);
      const g = x.createLinearGradient(x0 - 30, 0, x0 + o.edge, 0); g.addColorStop(0, 'rgba(0,0,0,0)'); g.addColorStop(1, 'rgba(0,0,0,1)');
      x.fillStyle = g; x.fillRect(0, 0, W, Hh); x.restore();
    }
    return l;
  }
  function face(c, kind, cx, cy, s) {
    const gr = c.createRadialGradient(cx - s * 0.3, cy - s * 0.3, s * 0.1, cx, cy, s * 1.1);
    gr.addColorStop(0, gy(238)); gr.addColorStop(1, gy(118));
    c.fillStyle = gr; c.beginPath();
    if (kind === 'cat') {
      c.ellipse(cx, cy + s * 0.08, s * 0.95, s * 0.8, 0, 0, 7); c.fill();
      c.beginPath(); c.moveTo(cx - s * 0.9, cy - s * 0.2); c.lineTo(cx - s * 0.78, cy - s * 1.05); c.lineTo(cx - s * 0.3, cy - s * 0.65); c.fill();
      c.beginPath(); c.moveTo(cx + s * 0.9, cy - s * 0.2); c.lineTo(cx + s * 0.78, cy - s * 1.05); c.lineTo(cx + s * 0.3, cy - s * 0.65); c.fill();
      c.fillStyle = gy(20); c.beginPath(); c.ellipse(cx - s * 0.36, cy - s * 0.05, s * 0.14, s * 0.11, 0, 0, 7); c.ellipse(cx + s * 0.36, cy - s * 0.05, s * 0.14, s * 0.11, 0, 0, 7); c.fill();
      c.beginPath(); c.moveTo(cx - s * 0.1, cy + s * 0.18); c.lineTo(cx + s * 0.1, cy + s * 0.18); c.lineTo(cx, cy + s * 0.3); c.fill();
      c.strokeStyle = gy(235); c.lineWidth = 1.5; [-1, 1].forEach((sd) => { for (let k = 0; k < 3; k++) { c.beginPath(); c.moveTo(cx + sd * s * 0.3, cy + s * 0.3 + k * 4); c.lineTo(cx + sd * s * 1.05, cy + s * 0.2 + k * 10); c.stroke(); } });
    } else {
      c.ellipse(cx, cy, s * 0.72, s * 0.88, 0, 0, 7); c.fill();
      c.fillStyle = gy(60); c.beginPath(); c.ellipse(cx - s * 0.8, cy - s * 0.05, s * 0.28, s * 0.62, 0.25, 0, 7); c.ellipse(cx + s * 0.8, cy - s * 0.05, s * 0.28, s * 0.62, -0.25, 0, 7); c.fill();
      c.fillStyle = gy(215); c.beginPath(); c.ellipse(cx, cy + s * 0.42, s * 0.36, s * 0.28, 0, 0, 7); c.fill();
      c.fillStyle = gy(20); c.beginPath(); c.ellipse(cx - s * 0.28, cy - s * 0.2, s * 0.1, s * 0.1, 0, 0, 7); c.ellipse(cx + s * 0.28, cy - s * 0.2, s * 0.1, s * 0.1, 0, 0, 7); c.fill();
      c.beginPath(); c.ellipse(cx, cy + s * 0.3, s * 0.14, s * 0.09, 0, 0, 7); c.fill();
    }
  }
  function mugshot(c, x, y, w, kind, num, rot = 0) {
    const h = w * 1.25; c.save(); c.translate(x, y); c.rotate(rot);
    // soft cast shadow on the board (key light from upper left)
    c.save(); c.shadowColor = 'rgba(0,0,0,0.65)'; c.shadowBlur = 14; c.shadowOffsetX = 8; c.shadowOffsetY = 10;
    c.fillStyle = gy(230); c.fillRect(-w / 2, -h / 2, w, h); c.restore();
    const pg = c.createLinearGradient(-w / 2, -h / 2, w / 2, h / 2); pg.addColorStop(0, gy(248)); pg.addColorStop(1, gy(205));
    c.fillStyle = pg; c.fillRect(-w / 2, -h / 2, w, h);                             // glossy print border
    const bg = c.createLinearGradient(0, -h / 2, 0, h / 2); bg.addColorStop(0, gy(150)); bg.addColorStop(1, gy(82));
    c.fillStyle = bg; c.fillRect(-w / 2 + 8, -h / 2 + 8, w - 16, h - 16);           // studio backdrop, top-lit
    c.strokeStyle = gy(95, 0.8); c.lineWidth = 1; for (let k = 1; k < 6; k++) { c.beginPath(); c.moveTo(-w / 2 + 8, -h / 2 + 8 + k * (h - 16) / 6); c.lineTo(w / 2 - 8, -h / 2 + 8 + k * (h - 16) / 6); c.stroke(); }
    face(c, kind, 0, -h * 0.1, w * 0.26);
    c.fillStyle = gy(22); c.fillRect(-w * 0.36, h * 0.18, w * 0.72, h * 0.22);          // booking placard
    c.fillStyle = gy(70); c.fillRect(-w * 0.36, h * 0.18, w * 0.72, 2);
    c.fillStyle = gy(235); c.textAlign = 'center'; c.font = `700 ${Math.max(24, Math.round(w * 0.2))}px "Oswald"`; c.fillText(kind.toUpperCase(), 0, h * 0.3);
    c.font = `400 ${Math.round(w * 0.08)}px "Courier Prime"`; c.fillText('No. ' + num, 0, h * 0.37);
    c.strokeStyle = gy(60, 0.5); c.lineWidth = 1; c.strokeRect(-w / 2 + 8.5, -h / 2 + 8.5, w - 17, h - 17);
    // curled bottom-right corner lifting off the board
