            const fall = Math.pow(1 - d / R2, 1.5) * H.smooth(-0.6, 0.4, Math.cos(Math.atan2(dy, dx) - ang * 2));
            const warp = nz.n2(dx * 0.06 + ang, dy * 0.06) * 2.5;
            Hh[y * w + x] += Math.sin(d * 1.6 + warp) * 0.22 * fall;
