        ctx.fillStyle = g; ctx.fillRect(0, 0, W, H_);
      }

      // ---------- pressed clay letters on the wall ----------
      {
        const txt = 'ASK ME ANYTHING';
        const cols = ['#f2c14e', '#f07b5a', '#f6efe3', '#ef8fb0', '#a8dd8a'];
        ctx.save(); ctx.font = '700 92px "Fredoka"';
