      }
      c.putImageData(img, 0, 0);
      // kozo fibres
      const rf = H.rng(55);
      for (let i = 0; i < 260; i++) {
        const x = rf.range(0, W), y = rf.range(0, HH), l = rf.range(10, 40), a = rf.range(0, Math.PI * 2);
        c.strokeStyle = rf() < 0.5 ? 'rgba(255,250,235,0.22)' : 'rgba(120,95,60,0.12)'; c.lineWidth = rf.range(0.5, 1.1);
