      // ---- panel 3: practice
      pen(11.2, 12.8, 0.45, pan(450)); // the accuracy line draws
      pen(11.3, 11.8, 0.6, pan(200)); // "starts at 61%"
      pen(11.6, 11.9, 0.5, pan(110)); // its leader
