      [[0.25, 0.8], [0.7, 0.3], [0.45, 0.9]].forEach(([a, b], i) => knob(ctx, 1055 + i * 92, 604, 25, H.lerp(a, b, adj) + (t < 8.9 ? Math.sin(t * 2 + i) * 0.02 : 0), 'W' + (i + 1), t > 8.85 && t < 9.6));
