      const tooth = (f2[i] - 128) / 128, broad = (f1[i] - 128) / 128, streak = (f1[i + 1] - 128) / 128, fine = (f2[i + 2] - 128) / 128;
      const hh = lhash(x, y, 1);
      const pg = 1 + (hh - 0.5) * 0.05 + tooth * 0.015 + streak * 0.018 + broad * 0.012;
      cr *= pg; cg *= pg; cb *= pg;
      const u = x * 0.85 + y * 0.55;
