{
  // ---------------------------------------------------------------
  // Impasto oil — thousands of loaded strokes along a swirling flow field,
  // each one raised off the canvas (height map) and lit for 3-D paint relief
  // ---------------------------------------------------------------
  const C = (r, g, b) => [r, g, b];
  const jit = (c, r, a) => [c[0] + r.gauss() * a, c[1] + r.gauss() * a, c[2] + r.gauss() * a];
