    oc.translate(8, 8);
    for (let y = 0; y < mh; y += step * 0.8) for (let x = 0; x < mw; x += step) {
      const xx = x + r.range(-1.5, 1.5), yy = y + r.range(-1.5, 1.5), k = ((yy | 0) * mw + (xx | 0)) * 4 + 3;
