  }
  function impCache() {
    if (IXC) return IXC;
    const C0 = { bg: impBackground(), text: new Map() };
    // painted cat & dog pictures (little framed canvases)
    const animal = (dog) => {
      const m = H.layer(200, 200), c = m.getContext('2d'); c.fillStyle = '#000';
      c.fillRect(0, 0, 200, 200);
