    let cv = C0.text.get(key);
    if (cv) return cv;
    const m = H.layer(4, 4).getContext('2d'); m.font = `${font} ${size}px "${family}"`;
    const w = Math.ceil(m.measureText(str).width) + 10, h = Math.ceil(size * 1.3);
