  }
  // gradated screentone (gradation tone) in a w x h box: density lerps d0 -> d1 along y. Cached.
  const GTONES = {};
  function gradTone(w, h, d0, d1, y0 = 0, y1 = h, fx0 = w, fx1 = w + 1) {
    const key = [w, h, d0, d1, y0, y1, fx0, fx1].join(',');
    if (!GTONES[key]) {
