    const BL = [[300, 170, '#7a2bff'], [900, 600, '#2b6bff'], [1400, 220, '#ff2bd6'], [1900, 620, '#00d1ff'], [2300, 200, '#ff7a1a'], [2800, 560, '#ff2bd6'], [3300, 220, '#7a2bff'], [3700, 600, '#ff7a1a'], [-200, 600, '#00d1ff']];
