    const frost = (t0, p, g = 1) => { k.noise(t0, { dur: 0.6, color: 'pink', filter: 'bandpass', f: [[0, 700], [0.35, 1500], [0.6, 1100]], q: 0.8, gain: 0.06 * g, a: 0.12, pan: p, verb: 0.2 }); tap(t0 + 0.28, 880, 0.7 * g, p); };
