    readsPixels: true,
    explainerDuration: 14.5,
    explainerNote: 'The bath is the model: examples land as colour drops, a new picture is a red probe drop that the flow drags toward its guess, the error is a stylus counter-stroke and the adjustment a comb pass that puts the pattern in order; scenes change by lifting the printed sheet off the bath, labels are bookbinder paper labels and arrows are inked stylus strokes.',
    explainer(ctx, W, H_, t) { explainPM(ctx, W, H_, t); },
    // Sound: the marbling bath. Colour drops land with small low water plops (pitch from drop size, pan from position,
    // throttled), the stylus and its counter-stroke are soft watery drags across the size, comb passes are a fuller
    // swish with the tines riffling through, scene changes are the wet sheet peeled off the bath, and the bookbinder
    // labels set down with a soft paper tap. A quiet pad sits under it. Timings mirror explainPM / mHook..mTake above.
    explainerSound(k) {
      const D = 14.5, E = H.ease;
      const pan = (px) => H.clamp((px / 1280) * 2 - 1, -1, 1) * 0.7;
      const when = (t0, t1, ease, u) => { for (let i = 0; i <= 400; i++) { const t = t0 + ((t1 - t0) * i) / 400; if (ease(i / 400) >= u - 1e-6) return t; } return t1; };
      // a colour drop meeting the size: short low bubble plop (stays under ~1 kHz) with a soft body
      const plop = (t, f, g, p) => { k.tone(t, { f: [[0, f], [0.045, f * 2.1]], dur: 0.075, gain: 0.13 * g, a: 0.002, pan: p }); k.tone(t, { f: [[0, 140], [0.06, 90]], dur: 0.08, gain: 0.1 * g, pan: p }); k.noise(t, { dur: 0.03, filter: 'lowpass', f: 700, gain: 0.08 * g, a: 0.001, pan: p }); };
      // label set down on the bench
      const label = (t0, p, g = 1) => { const t = t0 + 0.06; k.withMinor(() => { k.noise(t, { dur: 0.05, filter: 'bandpass', f: 1000, q: 0.7, gain: 0.12 * g, a: 0.003, pan: p }); k.tone(t, { f: 150, dur: 0.05, gain: 0.07 * g, pan: p }); }); };
      // stylus dragged through the bath from pan a to b over dur
      const drag = (t, dur, a, b, g = 1) => {
        const steps = 6; for (let i = 0; i < steps; i++) { const u = i / steps; k.noise(t + u * dur, { dur: dur / steps + 0.08, color: 'pink', filter: 'bandpass', f: 380 + 380 * Math.sin(Math.PI * (u + 0.08)), q: 1.6, gain: 0.13 * g * Math.sin(Math.PI * (u + 0.1)), a: 0.04, pan: a + (b - a) * u }); }
        k.tone(t + dur * 0.3, { f: [[0, 220], [0.05, 420]], dur: 0.07, gain: 0.05 * g, pan: a + (b - a) * 0.3, minor: true });
        k.tone(t + dur * 0.7, { f: [[0, 260], [0.05, 500]], dur: 0.07, gain: 0.04 * g, pan: a + (b - a) * 0.7, minor: true });
      };
      // comb pass: a swish with the tines riffling through the size
      const comb = (t, dur, g = 1) => {
        k.noise(t, { dur: dur + 0.1, color: 'pink', filter: 'lowpass', f: [[0, 500], [dur * 0.5, 1100], [dur + 0.1, 400]], gain: 0.13 * g, a: dur * 0.35 });
        const r = H.rng(Math.round(t * 100)); k.withMinor(() => { for (let x = 0.03; x < dur; x += 0.045 + r() * 0.03) k.noise(t + x, { dur: 0.03, filter: 'bandpass', f: 600 + r() * 500, q: 2, gain: 0.07 * g * Math.sin(Math.PI * x / dur), a: 0.008, pan: (x / dur - 0.5) * 0.8 }); });
      };
      // wet sheet peeled off the bath, left edge first (D = 0.55, inOut)
      const peel = (t0) => {
        const r = H.rng(Math.round(t0 * 10));
        k.noise(t0, { dur: 0.6, color: 'pink', filter: 'bandpass', f: [[0, 500], [0.3, 1200], [0.6, 600]], q: 0.9, gain: 0.12, a: 0.25 });
        k.withMinor(() => { for (let x = 0.04; x < 0.55; x += 0.025 + r() * 0.03) { const u = x / 0.55; k.noise(t0 + x, { dur: 0.025, filter: 'bandpass', f: 700 + r() * 800, q: 1.2, gain: 0.1 * Math.sin(Math.PI * u) + 0.02, a: 0.003, pan: -0.7 + 1.4 * E.inOut(u) }); } });
        k.noise(t0 + 0.5, { dur: 0.12, color: 'brown', filter: 'lowpass', f: 300, gain: 0.12, a: 0.01 }); // last of it lets go of the size
      };
      const busy = []; // drop times: counter clicks step around them so neither masks the other
      const counter = (t0, t1, ease, steps, rate, p) => { let last = -1, prev = 0;
        for (let t = t0; t <= t1; t += 0.002) { const s = Math.floor(ease(H.clamp((t - t0) / (t1 - t0))) * steps); if (s !== prev && t - last >= 1 / rate && !busy.some((b) => t > b - 0.02 && t < b + 0.07)) { k.play('tock', t, { f: 700, gain: 0.38, pan: p, minor: true }); last = t; } prev = s; } };

      k.bed('room', 0, D, { gain: 0.3 });
      k.music('pad', 0, D, { bpm: 64, gain: 0.35, chords: [['D3', 'A3', 'C4', 'F4'], ['G2', 'D3', 'B3', 'F4'], ['C3', 'G3', 'C4', 'E4'], ['A2', 'E3', 'A3', 'C4']] });

      // ---- hook: title label pops (back 0.15-0.5), slides to the corner (1.75-2.3)
      label(when(0.15, 0.5, E.back, 1) - 0.06, 0, 1.6);
      k.noise(1.75, { dur: 0.55, color: 'pink', filter: 'lowpass', f: [[0, 600], [0.55, 280]], gain: 0.028, a: 0.2, minor: true });

      // ---- data: peel, then 95 drops at ti = 2.5 + 3.1 (i/95)^0.85 (same seeded draws as battal), labels, counter
      peel(2.4);
      { const r = H.rng(77); let last = -1;
        for (let i = 0; i < 95; i++) {
          const x = r.range(-40, 1320); r.range(-40, 760); const rad = r.range(44, 84); r(); r();
          const ti = 2.5 + 3.1 * Math.pow(i / 95, 0.85);
          if (ti - last < (i < 4 ? 0.1 : 0.16)) continue; last = ti; busy.push(ti);
          k.withMinor(() => plop(ti, 520 - rad * 3, i < 4 ? 1.2 : 0.8, pan(x)));
        } }
      label(2.9, 0.5); label(3.2, 0.55);
      counter(2.72, 4.98, E.inOut, 30, 8, -0.6);
      label(4.94, -0.6, 1.5); k.tone(5.0, { f: 'D3', dur: 0.7, gain: 0.1, a: 0.01, verb: 0.3, pan: -0.5 }); // 1,000,000 lands

      // ---- loop: peel, probe drop, guess drag, wrong, counter-stroke, comb, guess again, cat ✓
      peel(6.0);
      plop(6.35, 300, 1.4, 0); plop(6.42, 380, 0.7, 0); plop(6.5, 420, 0.5, 0); // the red ring drops
      label(6.35, 0);
      drag(6.8, 0.5, -0.1, 0.6); // the flow pulls the probe toward DOG
      label(7.3, 0.5);
      k.play('stroke', 7.85, { material: 'brush', dur: 0.2, gain: 1.4, pan: pan(1150), minor: true }); // red ring round DOG
      label(7.95, 0.5, 1.3);
      k.play('tock', 7.97, { f: 300, gain: 0.7, pan: pan(1100) }); k.play('tock', 8.13, { f: 225, gain: 0.7, pan: pan(1100) }); // check: wrong
      k.play('thud', 7.97, { f: 100, gain: 0.45, pan: pan(1100) });
      drag(8.35, 0.5, 0.6, -0.1, 1.1); // counter-stroke pulls it back
      label(8.4, 0.1);
      label(8.95, 0);
      comb(8.95, 0.5, 0.75); // adjust: the comb orders the bath
      drag(9.45, 0.4, 0, -0.6); // now the flow pulls it to CAT
      label(9.85, -0.4, 1.3);
      ['G4', 'D5'].forEach((n, i) => k.play('ding', 9.88 + i * 0.09, { f: n, gain: 0.5, pan: -0.4 })); // cat ✓

      // ---- progress: peel, comb passes (rounds = floor(5 inOut(p))), red ink chart, counter, 97%
      peel(10.5);
      label(10.75, 0.4);
      for (let r = 0; r < 3; r++) { const a = when(10.85, 12.3, E.inOut, r / 5 + 1e-4), b = when(10.85, 12.3, E.inOut, (r + 1) / 5); comb(a, b - a, 0.6 - r * 0.12); busy.push(a + (b - a) / 2); }
      k.play('stroke', 10.9, { material: 'brush', dur: 1.4, gain: 0.35, pan: -0.4, minor: true });
      counter(10.86, 12.28, E.inOut, 36, 8, -0.5);
      k.play('impact', 12.3, { gain: 1.0, pan: -0.4 });
      plop(12.3, 180, 2.2, -0.3);
      ['D3', 'A3', 'F#4', 'A4'].forEach((n, i) => k.tone(12.32 + i * 0.03, { f: n, type: 'triangle', dur: 1.3, gain: 0.07, a: 0.01, verb: 0.35, filter: 'lowpass', f2: 1800, pan: (i - 1.5) * 0.25 })); // the 97% bloom
      k.play('stroke', 12.32, { material: 'brush', dur: 0.24, gain: 0.8, pan: -0.4, minor: true }); // red ring

      // ---- takeaway: peel back to the finished sheet, labels pop, resolve
      peel(13.0);
      const tk = when(13.25, 13.6, E.back, 1);
      label(tk - 0.06, 0, 1.6);
      ['G2', 'D3', 'B3', 'D4', 'G4'].forEach((n, i) => k.tone(tk + 0.05 + i * 0.05, { f: n, type: 'triangle', dur: 1.2, gain: 0.07, a: 0.01, verb: 0.35, filter: 'lowpass', f2: 1800, pan: (i - 2) * 0.2 }));
    },
    draw(ctx, W, H_, t) {
      const r = H.rng(2024);
      const polys = [];
      const ML = 3.2;
      const drop = (x, y, rad, col) => {
        applyOp(polys, T.drop({ x, y, r: rad }), ML);
        polys.push({ pts: circle(x, y, rad), col });
      };
      // a drop lands at time ti and blooms outward (radius eases to full) — later drops wait
      const land = (ti, x, y, rad, col, dur = 0.3) => {
        if (t < ti) return;
        const g = H.ease.out(H.clamp((t - ti) / dur));
        drop(x, y, Math.max(0.5, rad * g), col);
      };
      const P = (a, b) => H.ease.inOut(H.clamp((t - a) / (b - a)));
      const op = (k, f) => { if (k > 1e-4) applyOp(polys, f, ML); };
      // 1) battal ground: rows of drops sprinkled from the brush
      const ground = ['indigo', 'sand', 'sky', 'indigo', 'cream', 'teal', 'indigo', 'slate', 'sky', 'indigo', 'sand', 'ochre'];
      for (let i = 0; i < 270; i++) {
        land(0.05 + 2.1 * Math.pow(i / 270, 0.9), r.range(-80, W + 80), r.range(-80, H_ + 80), r.range(28, 64), PAL[ground[i % ground.length]]);
      }
      // fine 'eyes' sprinkled into the stone before raking (become streaks & veins)
      for (let i = 0; i < 160; i++) land(2.15 + 0.4 * (i / 160), r.range(-40, W + 40), r.range(-40, H_ + 40), r.range(3, 11), r.chance(0.55) ? PAL.cream : r.chance(0.5) ? PAL.ochre : PAL.ink, 0.15);
      // 2) gel-git: coarse alternating rake top<->bottom, then a wave, then the fine comb (tarak)
      const ph = 0.36;
      const rake = P(2.6, 3.7), wv = P(3.2, 4.0);
      op(rake, T.comb({ vertical: true, S: 80, off: 20 + ph * 30, a: 70 * rake, l: 22 }));
      op(wv, T.wave({ vertical: false, A: 18 * wv, L: 260, ph: 0.8 + ph }));

      // 3) sprinkle of small dark drops (opens tiny eyes in the ground)
      for (let i = 0; i < 40; i++) land(4.0 + 0.35 * (i / 40), r.range(0, W), r.range(0, H_), r.range(4, 9), r.chance(0.5) ? PAL.cream : PAL.ink, 0.12);
      // 4) focal tulip: concentric suminagashi rings dropped at one point
      const fx = 640, fy = 250;
      const rings = ['ochre', 'red', 'cream', 'red', 'cream', 'ochre', 'cream', 'red', 'ink', 'cream', 'red', 'cream', 'teal', 'cream', 'red', 'ochre', 'cream', 'red', 'cream', 'ink', 'cream'];
      rings.forEach((c, i) => land(4.35 + i * 0.045, fx, fy, i === 0 ? 34 : 24, PAL[c], 0.12));
      // side buds
      [[330, 420], [950, 420]].forEach(([bx, by], k) => {
        ['red', 'cream', 'ochre', 'cream', 'red', 'cream', 'ink', 'cream', 'red'].forEach((c, i) => land(4.6 + k * 0.08 + i * 0.05, bx, by, i === 0 ? 20 : 15, PAL[c], 0.12));
      });
      // stem + leaves: a column of small green drops and two leaf drops
      for (let y = 470; y < 700; y += 24) land(5.2 + (y - 470) / 230 * 0.25, fx + Math.sin(y * 0.02) * 4, y, 9, PAL.green, 0.12);
      land(5.45, fx - 62, 560, 26, PAL.green, 0.2); land(5.5, fx + 62, 600, 24, PAL.green, 0.2);
      // 5) stylus: pull through each flower to form the tulip; stem and leaves pulled too
      const p0 = P(5.6, 6.4), p1 = P(5.9, 6.5), p2 = P(6.05, 6.6), p3 = P(6.3, 6.8), swl = P(6.4, 7.0);
      op(p0, T.tine({ x: fx, y: 0, mx: 0, my: 1, a: 260 * p0, l: 16 }));
      op(p1, T.tine({ x: 330, y: 0, mx: 0, my: -1, a: 120 * p1, l: 10 }));
      op(p2, T.tine({ x: 950, y: 0, mx: 0, my: -1, a: 120 * p2, l: 10 }));
      op(p3, T.tine({ x: fx - 62, y: 560, mx: -0.6, my: -0.8, a: 70 * p3, l: 12 }));
      op(p3, T.tine({ x: fx + 62, y: 600, mx: 0.6, my: -0.8, a: 70 * p3, l: 12 }));
      // a slight lateral swirl as the sheet is laid (keeps it from looking rigid)
      op(swl, T.wave({ vertical: true, A: 5 * swl, L: 420, ph: 1.7 }));

      // ---------- render ----------
      ctx.fillStyle = PAL.sand; ctx.fillRect(0, 0, W, H_);
      for (const P of polys) {
        if (P.dead) continue;
        const p = P.pts;
        ctx.beginPath(); ctx.moveTo(p[0], p[1]);
        for (let i = 2; i < p.length; i += 2) ctx.lineTo(p[i], p[i + 1]);
        ctx.closePath();
        ctx.fillStyle = P.col; ctx.fill();
        // pigment concentrates at the rim of each floated drop: its own colour, darker
        ctx.strokeStyle = rimOf(P.col); ctx.lineWidth = 1; ctx.stroke();
      }

      ctx.save(); ctx.filter = 'blur(0.6px)'; ctx.drawImage(ctx.canvas, 0, 0, ctx.canvas.width, ctx.canvas.height, 0, 0, W, H_); ctx.restore();
      // ---------- flow-dragged pigment speckle + paper ----------
      // The rake is a vertical comb, so its inverse shift depends on x only: one combShift per column, and the
      // speckle noise is looked up from a cached pre-comb field (same formula as sampling it per pixel).
      const SPM = 260;
      if (!PM_SPK || PM_SPK.W !== W) {
        const nz = H.makeNoise(3), nz2 = H.makeNoise(8), rr = H.rng(9), RH = H_ + SPM * 2;
        const sp = new Float32Array(W * RH), lr = new Float32Array(W * H_);
        for (let y = 0; y < RH; y++) for (let x = 0; x < W; x++) { const py = y - SPM; sp[y * W + x] = (nz.n2(x * 0.08, py * 0.08) * 0.55 + nz2.n2(x * 0.35, py * 0.35) * 0.45) * 0.12; }
        for (let y = 0; y < H_; y++) for (let x = 0; x < W; x++) lr[y * W + x] = (x % 3 === 0 ? -0.025 : 0) + ((x + 9) % 64 < 1.5 ? -0.03 : 0) + (rr() - 0.5) * 0.04; // laid lines, fibre tooth
        PM_SPK = { W, sp, lr };
      }
      const img = ctx.getImageData(0, 0, W, H_), d = img.data;
      const combA = { vertical: true, S: 80, off: 20 + ph * 30, a: 70 * rake, l: 22 };
      const shiftX = new Int32Array(W);
      for (let x = 0; x < W; x++) shiftX[x] = Math.max(-SPM, Math.min(SPM, Math.round(-combShift(x, combA))));
      const { sp, lr } = PM_SPK;
      for (let y = 0; y < H_; y++) {
        for (let x = 0; x < W; x++) {
          const k = 1 + sp[(y + shiftX[x] + SPM) * W + x] + lr[y * W + x];
          const o = (y * W + x) * 4;
          d[o] *= k; d[o + 1] *= k; d[o + 2] *= k;
        }
      }
      ctx.putImageData(img, 0, 0);
      // cockle: broad soft light/dark undulation from the wetted sheet drying
      ctx.save(); ctx.globalCompositeOperation = 'soft-light'; ctx.imageSmoothingQuality = 'high'; ctx.drawImage(pmCockle(W, H_), 0, 0, W, H_); ctx.restore();
      // wet sheen gliding across the bath once the pattern is finished
      const gs = H.clamp((t - 6.7) / 1.3);
      if (gs > 0) {
        const gx = -400 + 2100 * H.ease.inOut(gs);
        const lg = ctx.createLinearGradient(gx - 260, 0, gx + 260, 200);
        lg.addColorStop(0, 'rgba(255,250,235,0)'); lg.addColorStop(0.5, 'rgba(255,250,235,0.13)'); lg.addColorStop(1, 'rgba(255,250,235,0)');
        ctx.save(); ctx.globalCompositeOperation = 'screen'; ctx.fillStyle = lg; ctx.fillRect(0, 0, W, H_); ctx.restore();
      }
      H.vignette(ctx, W, H_, 0.2, '40,25,10');
    },
  });
}

isotype.source:
{
  // ISOTYPE (Neurath / Arntz, Vienna Method) pictorial statistics.
  const PAPER = '#EFE7D4', INK = '#26231F', BLUE = '#294C63', RED = '#C2432C', OCHRE = '#D49A33';

  // Arntz-style standing figure in a 26 x 44 box, origin top-left
  function person(ctx, x, y, s) {
    ctx.save(); ctx.translate(x, y); ctx.scale(s, s);
    ctx.beginPath();
    ctx.arc(13, 5.2, 5.2, 0, Math.PI * 2);
    // torso with arms (one silhouette), rounded shoulders
    ctx.moveTo(4.5, 12.5);
    ctx.quadraticCurveTo(13, 10.6, 21.5, 12.5);
    ctx.quadraticCurveTo(25.5, 13.4, 25.5, 17.5);
    ctx.lineTo(25.5, 28.5); ctx.lineTo(22.5, 28.5); ctx.lineTo(22.2, 19.5);
    ctx.lineTo(21.0, 19.5); ctx.lineTo(20.8, 28.5);
    // legs
    ctx.lineTo(20.8, 44); ctx.lineTo(14.2, 44); ctx.lineTo(13.6, 30.5); ctx.lineTo(12.4, 30.5); ctx.lineTo(11.8, 44); ctx.lineTo(5.2, 44);
    ctx.lineTo(5.2, 28.5); ctx.lineTo(5.0, 19.5); ctx.lineTo(3.8, 19.5); ctx.lineTo(3.5, 28.5); ctx.lineTo(0.5, 28.5);
    ctx.lineTo(0.5, 17.5); ctx.quadraticCurveTo(0.5, 13.4, 4.5, 12.5);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  // compute unit: Arntz-style computer (monitor + keyboard) in a 32 x 44 box
  function chip(ctx, x, y, s, bg) {
    const ink = ctx.fillStyle;
    ctx.save(); ctx.translate(x, y); ctx.scale(s, s);
    // monitor body
    ctx.beginPath();
    ctx.moveTo(2, 4); ctx.lineTo(30, 4); ctx.quadraticCurveTo(32, 4, 32, 6); ctx.lineTo(32, 27);
    ctx.quadraticCurveTo(32, 29, 30, 29); ctx.lineTo(2, 29); ctx.quadraticCurveTo(0, 29, 0, 27); ctx.lineTo(0, 6);
    ctx.quadraticCurveTo(0, 4, 2, 4); ctx.closePath(); ctx.fill();
    // neck + foot
    ctx.fillRect(12.5, 29, 7, 5); ctx.fillRect(8, 33, 16, 2.5);
    // keyboard slab
    ctx.beginPath(); ctx.moveTo(3, 44); ctx.lineTo(6, 38.5); ctx.lineTo(26, 38.5); ctx.lineTo(29, 44); ctx.closePath(); ctx.fill();
    // screen (negative space) with a single bright prompt line
    ctx.fillStyle = bg; ctx.fillRect(4, 8, 24, 17);
    ctx.fillStyle = ink; ctx.fillRect(7, 11, 10, 2.6); ctx.fillRect(7, 16, 14, 2.6); ctx.fillRect(7, 21, 6, 2.6);
    ctx.restore();
  }

  // data-centre (factory-like silhouette) for the key
  function factory(ctx, x, y, s) {
    ctx.save(); ctx.translate(x, y); ctx.scale(s, s);
    ctx.beginPath();
    ctx.moveTo(0, 44); ctx.lineTo(0, 22); ctx.lineTo(9, 16); ctx.lineTo(9, 22); ctx.lineTo(18, 16); ctx.lineTo(18, 22);
    ctx.lineTo(27, 16); ctx.lineTo(27, 6); ctx.lineTo(33, 6); ctx.lineTo(33, 44); ctx.closePath();
    ctx.fill(); ctx.restore();
  }

  // ---- explainer pictograms (Arntz-style flat silhouettes) ----
  function catPic(ctx, x, y, s, bg) {
    ctx.save(); ctx.translate(x, y); ctx.scale(s, s);
    ctx.beginPath(); ctx.arc(14, 12, 7.5, 0, 7);
    ctx.moveTo(7.2, 9); ctx.lineTo(8, -0.5); ctx.lineTo(13, 5); ctx.closePath();
    ctx.moveTo(20.8, 9); ctx.lineTo(20, -0.5); ctx.lineTo(15, 5); ctx.closePath();
    ctx.moveTo(8.5, 19); ctx.bezierCurveTo(1, 28, 2, 44, 5, 44); ctx.lineTo(23, 44); ctx.bezierCurveTo(26, 44, 27, 28, 19.5, 19); ctx.closePath();
    ctx.fill();
    ctx.lineWidth = 3.4; ctx.lineCap = 'round'; ctx.strokeStyle = ctx.fillStyle;
    ctx.beginPath(); ctx.moveTo(22, 42); ctx.quadraticCurveTo(32, 40, 29, 28); ctx.stroke();
    ctx.fillStyle = bg; ctx.fillRect(13.3, 31, 1.4, 13);
    ctx.beginPath(); ctx.arc(11, 11.5, 1.3, 0, 7); ctx.arc(17, 11.5, 1.3, 0, 7); ctx.fill();
    ctx.restore();
  }
  function dogPic(ctx, x, y, s, bg) {
    ctx.save(); ctx.translate(x, y); ctx.scale(s, s);
    ctx.beginPath();
    ctx.moveTo(7, 6); ctx.quadraticCurveTo(7, 1, 13, 1); ctx.lineTo(19, 1); ctx.quadraticCurveTo(23, 1, 23, 6); ctx.lineTo(23, 9); ctx.lineTo(30, 10); ctx.quadraticCurveTo(32, 14, 29, 17); ctx.lineTo(21, 18);
    ctx.bezierCurveTo(27, 26, 27, 44, 24, 44); ctx.lineTo(5, 44); ctx.bezierCurveTo(2, 44, 1, 28, 8, 18); ctx.quadraticCurveTo(6, 12, 7, 6); ctx.closePath();
    ctx.fill();
    ctx.lineWidth = 3.4; ctx.lineCap = 'round'; ctx.strokeStyle = ctx.fillStyle;
    ctx.beginPath(); ctx.moveTo(5, 40); ctx.quadraticCurveTo(-3, 36, -1, 27); ctx.stroke();
    ctx.fillStyle = bg; ctx.fillRect(14.3, 31, 1.4, 13);
    ctx.beginPath(); ctx.arc(18, 7.5, 1.4, 0, 7); ctx.fill();
    ctx.beginPath(); ctx.moveTo(8, 4); ctx.quadraticCurveTo(4, 9, 7, 16); ctx.lineTo(9.5, 15); ctx.quadraticCurveTo(8.5, 9, 10.5, 5); ctx.closePath(); ctx.fill();
    ctx.restore();
  }
  // flat ISOTYPE arrow (shaft + head), optionally curved via a quadratic control point
  function flatArrow(ctx, x0, y0, x1, y1, w, p = 1, cx = null, cy = null) {
    if (p <= 0) return;
    const pts = [];
    const n = 30;
    for (let k = 0; k <= n * p; k++) {
      const u = k / n;
      if (cx === null) pts.push([H.lerp(x0, x1, u), H.lerp(y0, y1, u)]);
      else { const a = (1 - u) * (1 - u), b = 2 * u * (1 - u), c = u * u; pts.push([a * x0 + b * cx + c * x1, a * y0 + b * cy + c * y1]); }
    }
    if (pts.length < 2) return;
    const [ex, ey] = pts[pts.length - 1], [px, py] = pts[pts.length - 2];
    const an = Math.atan2(ey - py, ex - px);
    ctx.save(); ctx.lineWidth = w; ctx.lineCap = 'butt'; ctx.lineJoin = 'round'; ctx.strokeStyle = ctx.fillStyle;
    ctx.beginPath(); pts.slice(0, -1).forEach(([x, y], i) => (i ? ctx.lineTo(x, y) : ctx.moveTo(x, y)));
    ctx.lineTo(ex - Math.cos(an) * w * 0.9, ey - Math.sin(an) * w * 0.9); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(ex + Math.cos(an) * w * 0.9, ey + Math.sin(an) * w * 0.9);
    ctx.lineTo(ex - Math.cos(an) * w * 0.9 + Math.cos(an + Math.PI / 2) * w * 1.25, ey - Math.sin(an) * w * 0.9 + Math.sin(an + Math.PI / 2) * w * 1.25);
    ctx.lineTo(ex - Math.cos(an) * w * 0.9 - Math.cos(an + Math.PI / 2) * w * 1.25, ey - Math.sin(an) * w * 0.9 - Math.sin(an + Math.PI / 2) * w * 1.25);
    ctx.closePath(); ctx.fill(); ctx.restore();
  }
  function checkPic(ctx, x, y, s) { ctx.save(); ctx.translate(x, y); ctx.scale(s, s); ctx.lineWidth = 7; ctx.lineCap = 'butt'; ctx.lineJoin = 'miter'; ctx.strokeStyle = ctx.fillStyle; ctx.beginPath(); ctx.moveTo(2, 22); ctx.lineTo(11, 31); ctx.lineTo(30, 6); ctx.stroke(); ctx.restore(); }
  function crossPic(ctx, x, y, s) { ctx.save(); ctx.translate(x, y); ctx.scale(s, s); ctx.lineWidth = 7; ctx.lineCap = 'butt'; ctx.strokeStyle = ctx.fillStyle; ctx.beginPath(); ctx.moveTo(3, 3); ctx.lineTo(29, 29); ctx.moveTo(29, 3); ctx.lineTo(3, 29); ctx.stroke(); ctx.restore(); }

  const ROWS = [
    { yr: '2000', p: 4.5, c: 0.25 },
    { yr: '2005', p: 5.25, c: 0.5 },
    { yr: '2010', p: 6.5, c: 1.5 },
    { yr: '2015', p: 7.75, c: 3.5 },
    { yr: '2020', p: 9.25, c: 7.25 },
    { yr: '2025', p: 10.5, c: 13.5 },
  ];

  // ---- litho finish, cached once per size ----
  // paper mottle: one fbm per 4x4 px, drawn upscaled with smoothing (no blocky squares, no per-frame noise)
  const MOTTLE = {};
  function mottle(W, H_, oct) {
    const key = W + 'x' + H_ + 'x' + oct;
    if (MOTTLE[key]) return MOTTLE[key];
    const w = Math.ceil(W / 4), h = Math.ceil(H_ / 4), L = H.layer(w, h), c = L.getContext('2d'), id = c.createImageData(w, h);
    const nz = H.makeNoise(4);
    for (let j = 0; j < h; j++) for (let i = 0; i < w; i++) {
      const v = nz.fbm2((i * 4 + 2) * 0.006, (j * 4 + 2) * 0.006, oct), o = (j * w + i) * 4;
      id.data[o] = 150; id.data[o + 1] = 120; id.data[o + 2] = 80; id.data[o + 3] = v > 0.05 ? Math.min(255, (v - 0.05) * 0.06 * 255) : 0;
    }
    c.putImageData(id, 0, 0);
    return (MOTTLE[key] = L);
  }
  function lithoFinish(ctx, W, H_, oct) {
    ctx.save(); ctx.globalCompositeOperation = 'multiply'; ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = 'high';
    ctx.drawImage(mottle(W, H_, oct), 0, 0, W, H_); ctx.restore();
  }
  // ink film wear: where the litho ink did not fully take. Low-frequency density drift + fine pinholes and a few
  // dry streaks, removed from the ink layer with destination-out so paper shows through the flat fills.
  const WEAR = {};
  function wear(W, H_) {
    const key = W + 'x' + H_;
    if (WEAR[key]) return WEAR[key];
    const L = H.layer(W, H_), c = L.getContext('2d');
    const w = Math.ceil(W / 3), h = Math.ceil(H_ / 3), S = H.layer(w, h), sc = S.getContext('2d'), id = sc.createImageData(w, h);
    const nz = H.makeNoise(23), rf = H.rng(5);
    for (let j = 0; j < h; j++) for (let i = 0; i < w; i++) {
      const v = nz.fbm2(i * 0.05, j * 0.05, 3), f = nz.n2(i * 0.6 + 40, j * 0.6), o = (j * w + i) * 4;
      // coarse density drift + an 'orange-peel' fine stipple where the ink film is thin
      const a = Math.max(0, v * 0.5 + 0.5 - 0.4) * 0.34 + Math.max(0, f) * 0.07 + rf() * 0.035;
      id.data[o + 3] = Math.min(255, a * 255);
    }
    sc.putImageData(id, 0, 0);
    c.imageSmoothingEnabled = true; c.drawImage(S, 0, 0, W, H_);
    const r = H.rng(77);
    c.fillStyle = '#000';
    for (let n = 0; n < W * H_ * 0.0016; n++) {   // pinholes
      const x = r() * W, y = r() * H_, rr = 0.5 + r() * r() * 1.4;
      c.globalAlpha = 0.25 + r() * 0.55; c.beginPath(); c.arc(x, y, rr, 0, 7); c.fill();
    }
    c.globalAlpha = 0.09;
    for (let n = 0; n < 140; n++) {               // faint horizontal roller streaks
      const x = r() * W, y = r() * H_; c.fillRect(x, y, 20 + r() * 90, 0.8 + r() * 0.8);
    }
    c.globalAlpha = 1;
    return (WEAR[key] = L);
  }
  const INKL = {};
  function inkLayer(W, H_) {
    const key = W + 'x' + H_;
    const L = INKL[key] || (INKL[key] = H.layer(W, H_)), c = L.getContext('2d');
    c.setTransform(1, 0, 0, 1, 0, 0); c.globalAlpha = 1; c.globalCompositeOperation = 'source-over'; c.clearRect(0, 0, W, H_);
    return L;
  }
  function printInk(out, L, W, H_) {
    const c = L.getContext('2d');
    c.save(); c.setTransform(1, 0, 0, 1, 0, 0); c.globalAlpha = 1; c.globalCompositeOperation = 'destination-out'; c.drawImage(wear(W, H_), 0, 0); c.restore();
    out.save(); out.setTransform(1, 0, 0, 1, 0, 0); out.drawImage(L, 0, 0); out.restore();
  }

  function spaced(ctx, str, x, y, track, align) {
    let w = 0; for (const ch of str) w += ctx.measureText(ch).width + track; w -= track;
    let cx = align === 'center' ? x - w / 2 : align === 'right' ? x - w : x;
    ctx.textAlign = 'left';
    for (const ch of str) { ctx.fillText(ch, cx, y); cx += ctx.measureText(ch).width + track; }
  }

  registerStyle({
    id: 'isotype',
    name: 'ISOTYPE Pictograms',
    category: 'Data & Information',
    description: 'Vienna Method pictorial statistics: rows of identical flat pictograms where each symbol is a fixed quantity, partial symbols for remainders, three muted litho inks on a strict grid with geometric sans lettering.',
    motion: 'Title and key set first, the year column drops in, then symbols are stamped out row by row from the centre in stepped, rubber-stamp timing, the 2025 row of machines racing ahead; the litho paper breathes in the hold.',
    fonts: ['700 40px "Space Grotesk"', '400 18px "Space Grotesk"', '700 26px "Space Grotesk"', '400 14px "Space Grotesk"', '700 14px "Space Grotesk"', '700 96px "Space Grotesk"', '700 32px "Space Grotesk"', '400 24px "Space Grotesk"'],
    duration: 5.5,
    frameT: 5.4,
    readsPixels: true,
    draw(ctx, W, H_, t) {
      H.paper(ctx, W, H_, PAPER, 11, 0.02);
      const OUT = ctx, IL = inkLayer(W, H_); ctx = IL.getContext('2d');

      const CX = 640, colHalf = 56, pitch = 36, rowH = 66, top = 214;
      const s = 1.0;
      // stepped clock: the stamping runs "on twos" at 12 fps like a mechanical counter
      const ts = Math.floor(t * 12) / 12;
      const seg = (a, b) => H.clamp((ts - a) / (b - a));
      // per-icon stamp: invisible -> oversized impression (one step) -> settled
      const stampAt = (start) => (ts < start ? 0 : ts < start + 1 / 12 ? 0.5 : 1);

      // ---- title block ----
      ctx.fillStyle = INK; ctx.textBaseline = 'alphabetic';
      ctx.globalAlpha = seg(0, 0.34);
      ctx.font = '700 40px "Space Grotesk"'; spaced(ctx, 'PEOPLE AND MACHINES', CX, 86 - (1 - seg(0, 0.34)) * 8, 5, 'center');
      ctx.globalAlpha = seg(0.25, 0.6);
      ctx.font = '400 18px "Space Grotesk"';
      spaced(ctx, 'Workers and machines for AI in the computing industry, 2000–2025', CX, 120, 0.6, 'center');
      ctx.globalAlpha = 1;
      const rp = H.ease.out(seg(0.3, 0.75));
      ctx.fillStyle = INK; ctx.fillRect(CX - 300 * rp, 140, 600 * rp, 2);

      // ---- column heads with keys ----
      ctx.globalAlpha = seg(0.5, 0.84);
      ctx.font = '700 14px "Space Grotesk"';
      ctx.fillStyle = BLUE; person(ctx, CX - colHalf - 30, 156, 0.62);
      ctx.fillStyle = INK; spaced(ctx, 'WORKERS', CX - colHalf - 40, 176, 2.5, 'right');
      ctx.font = '400 14px "Space Grotesk"'; spaced(ctx, 'each figure = 1 million', CX - colHalf - 40, 194, 0.4, 'right');
      ctx.fillStyle = RED; chip(ctx, CX + colHalf + 6, 156, 0.62, PAPER);
      ctx.fillStyle = INK; ctx.font = '700 14px "Space Grotesk"'; spaced(ctx, 'AI COMPUTERS', CX + colHalf + 40, 176, 2.5, 'left');
      ctx.font = '400 14px "Space Grotesk"'; spaced(ctx, 'each machine = 100,000', CX + colHalf + 40, 194, 0.4, 'left');
      ctx.globalAlpha = 1;

      // ---- centre year column drops in ----
      const colP = H.ease.out(seg(0.6, 1.1));
      ctx.fillStyle = OCHRE;
      ctx.fillRect(CX - colHalf + 8, top - 6, (colHalf - 8) * 2, (ROWS.length * rowH - 2) * colP);

      // row timing: each row stamps outward from the column, rows in sequence
      const DT = 0.042;
      let rowStart = 1.15;
      ROWS.forEach((row, ri) => {
        const y = top + ri * rowH;
        const t0 = rowStart; rowStart += Math.max(Math.ceil(row.p), Math.ceil(row.c)) * DT + 0.05;
        // year
        if (ts >= 0.75 + ri * 0.06) { ctx.fillStyle = INK; ctx.font = '700 26px "Space Grotesk"'; spaced(ctx, row.yr, CX, y + 36, 1.5, 'center'); }
        // row hairline
        const hp = seg(t0 - 0.15, t0 + 0.35);
        if (ri && hp > 0) { ctx.fillStyle = 'rgba(38,35,31,0.18)'; const lw = (CX - colHalf - 70) * hp; ctx.fillRect(CX - colHalf - lw, y - 4, lw, 1); ctx.fillRect(CX + colHalf, y - 4, (W - 70 - CX - colHalf) * hp, 1); }

        // workers, growing leftward from the column; partial symbol on the outer end shows its inner part
        const pn = Math.ceil(row.p);
        for (let k = 0; k < pn; k++) {
          const frac = Math.min(1, row.p - k), a = stampAt(t0 + k * DT);
          if (a <= 0) continue;
          const x = CX - colHalf - 14 - (k + 1) * pitch + (pitch - 26 * s) / 2;
          ctx.save();
          if (frac < 1) { ctx.beginPath(); ctx.rect(x + 26 * s * (1 - frac), y, 26 * s * frac + 1, 60); ctx.clip(); }
          ctx.fillStyle = BLUE;
          if (a < 1) { ctx.translate(x + 13, y + 28); ctx.scale(1.14, 1.14); ctx.translate(-x - 13, -y - 28); ctx.globalAlpha = 0.8; }
          person(ctx, x, y + 6, s);
          ctx.restore();
        }
        // chips, growing rightward
        const cn = Math.ceil(row.c);
        for (let k = 0; k < cn; k++) {
          const frac = Math.min(1, row.c - k), a = stampAt(t0 + k * DT);
          if (a <= 0) continue;
          const cs = 0.88, x = CX + colHalf + 14 + k * pitch + (pitch - 32 * cs) / 2;
          ctx.save();
          if (frac < 1) { ctx.beginPath(); ctx.rect(x - 1, y, 32 * cs * frac + 1, 60); ctx.clip(); }
          ctx.fillStyle = RED;
          if (a < 1) { ctx.translate(x + 14, y + 30); ctx.scale(1.14, 1.14); ctx.translate(-x - 14, -y - 30); ctx.globalAlpha = 0.8; }
          chip(ctx, x, y + 6 + 44 * (1 - cs), cs, PAPER);
          ctx.restore();
        }
      });

      // ---- footer ----
      const fy = top + ROWS.length * rowH + 14;
      const fp = H.ease.out(seg(rowStart, rowStart + 0.4));
      ctx.fillStyle = INK; ctx.fillRect(70, fy, (W - 140) * fp, 2);
      ctx.globalAlpha = seg(rowStart + 0.2, rowStart + 0.6);
      ctx.font = '400 14px "Space Grotesk"'; ctx.fillStyle = INK;
      spaced(ctx, 'Partial symbols show fractions of a unit.  Figures are illustrative.', 70, fy + 28, 0.3, 'left');
      ctx.font = '700 14px "Space Grotesk"';
      spaced(ctx, 'AFTER THE VIENNA METHOD', W - 70, fy + 28, 2.2, 'right');
