    const bg2 = ctx.createLinearGradient(0, BY, 0, BY + 700); bg2.addColorStop(0, '#7b798c'); bg2.addColorStop(1, '#5e5c6e');
    bezPath(ctx, 3); ctx.fillStyle = bg2; ctx.fill();
