        if (t > 7.5) { // CHECK: wrong!
          const bl = Math.floor((t - 7.5) * 8) % 2 === 0 || t > 8.0;
          if (bl) cross(rx + 90, ry + 22, 46, RED, 1);
          if (bl) brackets(picX - 126, picY - 126, 252, 252, 26, RED, 1);
