      if (t > 7.95 && t < 9.4) redPencil(ctx, circ(O + 860, 366, 120, 52, 40, -0.6, -0.6 + Math.PI * 2.15), H.clamp((t - 7.95) / 0.35), 5);
      if (t > 8.1 && t < 9.4) { ctx.save(); ctx.fillStyle = 'rgba(178,52,40,0.85)'; ctx.font = 'italic 400 32px "Libre Baskerville"'; ctx.fillText('wrong!', O + 990, 296); ctx.restore(); }
      if (t > 12.6) redPencil(ctx, circ(G + 1060, 300, 170, 96, 40, -0.4, -0.4 + Math.PI * 2.15), H.clamp((t - 12.6) / 0.35), 6);
      if (t > 12.8) { ctx.save(); ctx.fillStyle = 'rgba(178,52,40,0.85)'; ctx.font = 'italic 400 30px "Libre Baskerville"'; ctx.fillText('97% — allowed', G + 930, 430); ctx.restore(); }
      ctx.restore();
      H.grain(ctx, W, H_, 0.05, 13 + Math.floor(t * 12));
    },
    // Sound: a quiet drafting room. Everything inked is a steel ruling pen scratching across hard paper (thin, dry,
    // no squeak); the machine's odometer drums clack; the examiner's red pencil is a softer, grainier graphite drag.
    // Camera moves along the sheet are the long sheet sliding under the lamp (a low smooth slide, no rustle).
    // All times copied from explainer() above.
    explainerSound(k) {
      // Chrome glitch: a noise buffer that starts within ~1e-8 s of a sample boundary (float error like 4.15 + 0.1 * 1 + 0.11)
      // spikes far above its gain. Put every start a quarter sample past the 48 kHz grid so none land there.
      { const k0 = k, sn = (t) => (Math.round(t * 48000) + 0.25) / 48000; k = { ...k0, play: (n, t, o) => k0.play(n, sn(t), o), tone: (t, o) => k0.tone(sn(t), o), noise: (t, o) => k0.noise(sn(t), o) }; }
      const D = 14.5;
      // screen pan for a sheet x at the camera's resting framings (FIG.4: x, FIG.5: zoom 1.3 on 1970, FIG.6: x-2560)
      const p4 = (x) => H.clamp(x / 640 - 1, -1, 1) * 0.6, p5 = (x) => H.clamp(((640 + (x - 1970) * 1.3) / 640) - 1, -1, 1) * 0.6, p6 = (x) => p4(x - 2560);
      // ruling pen: nib touches down (tiny dry tap), then a thin steel scratch for the stroke's length
      const pen = (a, d, g = 1, pan = 0, minor = true) => {
        k.noise(a, { dur: 0.018, filter: 'bandpass', f: 1900, q: 1.3, gain: 0.16 * g, a: 0.001, pan, minor });
        k.play('stroke', a, { material: 'pen', dur: d, gain: 2.7 * g, pan, minor });
        k.noise(a, { dur: d, filter: 'bandpass', f: 1200, q: 0.8, gain: 0.05 * g, a: Math.min(0.02, d / 3), hold: d * 0.6, pan, minor }); // a little body: the pen dragging on the rule
      };
      // red pencil: grainier, lower, softer than the steel pen
      const redPencil = (a, d, g = 1, pan = 0, minor = false) => k.play('stroke', a, { material: 'pencil', dur: d, gain: 0.9 * g, pan, minor });
      // odometer drum: a small, damped brass clack
      const drum = (t, g = 1, pan = 0, f = 1500) => k.withMinor(() => { k.noise(t, { dur: 0.03, filter: 'bandpass', f, q: 2.2, gain: 0.3 * g, a: 0.001, pan }); k.tone(t, { f: f * 0.2, type: 'triangle', dur: 0.04, gain: 0.07 * g, pan }); });
      // the long sheet sliding under the lamp: low, smooth, no paper crinkle
      const slide = (a, d, g = 1) => k.noise(a, { dur: d, color: 'brown', filter: 'bandpass', f: [[0, 220], [d * 0.5, 520], [d, 260]], q: 0.6, gain: 0.34 * g, a: d * 0.45, verb: 0.05 });

      k.bed('room', 0, D, { gain: 0.35 });
      k.bed('hiss', 0, D, { gain: 0.5 });

      // ---- BEAT 1: "HOW  DOES  AI  LEARN?" letters in left to right over 0..1.0 (21 chars), double rule 0.9..1.3
      [[0, 3], [5, 9], [11, 13], [15, 21]].forEach(([s, e], i) => pen(0.02 + (s / 21) * 0.98, ((e - s) / 21) * 0.98, 1.1, [-0.35, -0.12, 0.1, 0.3][i], i > 0));
      pen(0.9, 0.4, 1.3, 0, false); // ruled double underline: one long confident pull along the T-square
      pen(1.02, 0.28, 0.6, 0.05);
      slide(1.35, 0.85, 0.5); // title shrinks up into the title slot (1.35 -> 2.2)

      // ---- BEAT 2: FIG. 4 inks at 140 marks/s from 2.25 (tray + cards, then hopper, cabinet, odometer, gears ~3.05)
      pen(2.25, 0.14, 1.1, p4(280), false); // first mark of the figure
      { const xs = [280, 230, 340, 750, 750, 700, 750, 800, 750]; for (let i = 1; i < xs.length; i++) pen(2.25 + i * 0.09, 0.07, 0.75, p4(xs[i])); }
      // cards fly the arc into the hopper (5 cards, period 1/1.3 s, card k offset k*0.2/1.3); a light card flick as each drops in
      for (let c = 0; c < 5; c++) for (let n = 0; ; n++) {
        const t0 = 2.7 + (c * 0.2 + n) / 1.3, drop = t0 + 0.95 / 1.3;
        if (drop > 6.15) break;
        if ((c + n) % 2 === 0) k.noise(drop, { dur: 0.05, filter: 'bandpass', f: 1500, q: 0.8, gain: 0.11, a: 0.003, pan: p4(720), minor: true });
      }
      pen(2.9, 0.5, 0.9, p4(450)); // flow arrow arcs over to the hopper
      pen(3.0, 0.29, 0.6, p4(930)); // leader to the odometer
      pen(3.5, 0.24, 0.6, p4(220)); // 'labels' leader
      // odometer drums roll at 9 turns/s while the count runs (2.9 -> 5.6); clack per turn, softer while it barely moves
      for (let n = Math.ceil(2.9 * 9); n / 9 < 5.6 - 0.03; n++) {
        const t = n / 9, e = H.ease.inOut(H.clamp((t - 2.9) / 2.7)), sp = Math.min(1, 6 * e * (1 - e) + 0.25);
        drum(t, 0.55 + 0.45 * sp, p4(750), 1400 + e * 300);
      }
      // 1,000,000 locks in
      k.play('tock', 5.6, { f: 520, gain: 0.55, pan: p4(900) });
      k.play('thud', 5.6, { f: 110, gain: 0.22, pan: p4(900) });

      // ---- camera travels the sheet to FIG. 5 (6.0 -> 6.8)
      slide(6.0, 0.85, 1);
      // FIG. 5 inks at 170/s from 6.25 (cabinet, windows, three knobs ~6.53)
      pen(6.25, 0.12, 0.9, p5(1880));
      [1990, 1790, 1875, 1960].forEach((x, i) => pen(6.33 + i * 0.06, 0.05, 0.6, p5(x)));
      // the "?" card slides into the input slot (6.5 -> ~7.1, ease out), seats with a little click
      k.noise(6.5, { dur: 0.42, color: 'pink', filter: 'bandpass', f: [[0, 700], [0.4, 1300]], q: 0.8, gain: 0.12, a: 0.05, pan: p5(1560), minor: true });
      k.play('tock', 6.95, { f: 900, gain: 0.3, pan: p5(1640), minor: true });
      // guess window reveals "dog?" (7.15): the readout drum flips over
      drum(7.15, 1.2, p5(2120), 1200); k.play('tock', 7.17, { f: 640, gain: 0.45, pan: p5(2120) });
      pen(7.25, 0.24, 0.55, p5(2150)); // Guess leader
      pen(7.45, 0.3, 0.7, p5(2280)); // arrow to the reference tag
      pen(7.5, 0.12, 0.6, p5(2380)); // tag outline
      pen(7.6, 0.24, 0.55, p5(2380)); // Check leader
      // WRONG: two heavy ruled strokes cross out "dog?" (7.8 -> 7.925 -> 8.05), then the examiner's red ring (7.95 -> 8.3)
      pen(7.8, 0.12, 2.0, p5(2140), false); pen(7.925, 0.12, 2.0, p5(2140), false);
      k.play('error', 7.8, { f: 'F3', gain: 0.55, pan: p5(2140) });
      redPencil(7.95, 0.35, 1.2, p5(2140));
      // error signal: a dashed line ruled back to the knobs (8.25 -> 8.75), dash by dash
      for (let i = 0; i < 6; i++) pen(8.25 + i * 0.08, 0.045, 0.6, p5([2380, 2300, 2150, 1960, 1860, 1840][i]));
      pen(8.6, 0.24, 0.55, p5(1690)); // Adjust leader
      // knobs turn (quantized to 12 fps, 8.75 + i*0.12 over 0.5 s): one detent click per moving frame
      for (let f = Math.ceil(8.76 * 12); f / 12 < 9.49; f++) k.play('click', f / 12, { f: 900 + (f % 3) * 90, gain: 0.5, pan: p5(1875 + ((f % 3) - 1) * 85), minor: true });
      pen(9.15, 0.3, 0.7, p5(2080)); // loop return arrow
      // CORRECTION: "cat" turns up in the window (9.35), check mark inked (9.65)
      drum(9.35, 1.2, p5(2120), 1200); k.play('tock', 9.36, { f: 700, gain: 0.5, pan: p5(2120) });
      pen(9.65, 0.12, 1.4, p5(2200), false);
      k.play('success', 9.66, { f: 'G5', gain: 0.6, pan: p5(2200) });

      // ---- camera travels to FIG. 6 (10.3 -> 11.0)
      slide(10.3, 0.75, 1);
      pen(10.75, 0.1, 0.9, p6(2740), false); pen(10.85, 0.12, 0.6, p6(3060)); // axes and grid (inked at 260/s)
      pen(11.0, 1.5, 0.45, p6(3060)); // the curve inks along with the hatching under it (11.0 -> 12.5)
      { // accuracy drums: one clack per new value, at most 12/s, slowing as it settles
        const acc = (u) => 61 + 36 * (1 - Math.pow(1 - u, 2.3));
        let last = 61, lastT = -1;
        for (let t = 11.0; t < 12.5; t += 1 / 120) {
          const v = Math.round(acc(H.clamp((t - 11.0) / 1.5)));
          if (v !== last && t - lastT >= 1 / 12) { drum(t, 0.9, p6(3490), 1300 + (v - 61) * 12); last = v; lastT = t; }
        }
      }
      // 97 locks in (12.5) and the examiner rings it in red (12.6 -> 12.95): the big hit
      k.play('impact', 12.5, { gain: 1.1, pan: p6(3490) });
      k.play('ding', 12.52, { f: 'E5', gain: 0.5, pan: p6(3490) });
      redPencil(12.6, 0.35, 2.2, p6(3620));

      // ---- BEAT 5: the claim letters in (13.0 -> 13.7, 43 chars), then a ruled underline (13.75 -> 14.05)
      { const txt = 'I claim: More examples  →  better guesses.', n = txt.length, re = /\S+/g; let m;
        while ((m = re.exec(txt))) pen(13.0 + 0.7 * m.index / n, Math.max(0.04, 0.7 * m[0].length / n), 0.75, (m.index / n - 0.5) * 0.6); }
      pen(13.75, 0.3, 1.2, 0, false);
      ['C5', 'G5', 'E6'].forEach((f, i) => k.play('ding', 13.78 + i * 0.08, { f, gain: 0.4 - i * 0.07, pan: (i - 1) * 0.25 })); // resolve
    },

    // ===== END EXPLAINER =====
  });
}

bauhaus.source:
{
  // ---------- print helpers (local) ----------
  const fieldNoise = (w, h, seed, cell, oct, sx = 1, sy = 1) => {
    const nz = H.makeNoise(seed), gw = Math.ceil(w / cell) + 2, gh = Math.ceil(h / cell) + 2, g = new Float32Array(gw * gh);
    for (let j = 0; j < gh; j++) for (let i = 0; i < gw; i++) g[j * gw + i] = nz.fbm2(i * 0.35 * sx, j * 0.35 * sy, oct);
    const out = new Float32Array(w * h);
    for (let y = 0; y < h; y++) {
      const fy = y / cell, j = fy | 0, ty = fy - j;
      for (let x = 0; x < w; x++) {
        const fx = x / cell, i = fx | 0, tx = fx - i, k = j * gw + i;
        const a = g[k] + (g[k + 1] - g[k]) * tx, b = g[k + gw] + (g[k + gw + 1] - g[k + gw]) * tx;
        out[y * w + x] = a + (b - a) * ty;
      }
    }
    return out;
  };
  // deterministic noise fields are cached across frames (pure: same inputs -> same arrays)
  const CACHE = {};
  const cachedField = (key, ...a) => CACHE[key] || (CACHE[key] = fieldNoise(...a));

  // mottled ink coverage: modulates alpha of a layer
  const inkify = (layer, seed, mottle, speck) => {
    const c = layer.getContext('2d'), w = layer.width, h = layer.height, img = c.getImageData(0, 0, w, h), d = img.data;
    const n1 = cachedField('ink1' + seed, w, h, seed, 5, 3), n2 = cachedField('ink2' + seed, w, h, seed + 9, 40, 3), r = H.rng(seed + 3);
    for (let i = 0, p = 0; i < d.length; i += 4, p++) {
      if (!d[i + 3]) { r(); continue; }
      let a = 1 - mottle * Math.max(0, n1[p] * 1.6 + n2[p] * 0.9);
      if (r() < speck * (0.4 + Math.max(0, n2[p]) * 3)) a *= 0.25;
      d[i + 3] *= H.clamp(a, 0, 1);
    }
    c.putImageData(img, 0, 0);
  };

  const C = { cream: '#ece2c9', red: '#cf3a2a', yellow: '#efb526', blue: '#1f4f9b', black: '#1c1a18' };

  // ring helper
  const ring = (c, x, y, ro, ri) => { c.beginPath(); c.arc(x, y, ro, 0, Math.PI * 2); c.arc(x, y, ri, 0, Math.PI * 2, true); c.fill(); };

  // constructed geometric lettering (Bayer-like universal alphabet)
  const letter = (c, ch, x, base, xh, sw) => {
    const R = xh / 2;
    if (ch === 'o') { ring(c, x + R, base - R, R, R - sw); return xh; }
    if (ch === 'b') { c.fillRect(x, base - xh * 1.55, sw, xh * 1.55); ring(c, x + R, base - R, R, R - sw); return xh; }
    if (ch === 'r') {
      c.fillRect(x, base - xh, sw, xh);
      c.beginPath(); c.arc(x + R, base - R, R, Math.PI, Math.PI * 1.62); c.arc(x + R, base - R, R - sw, Math.PI * 1.62, Math.PI, true); c.fill();
      return xh * 0.66;
    }
    if (ch === 't') {
      c.fillRect(x + xh * 0.18, base - xh * 1.4, sw, xh * 1.4);
      c.fillRect(x, base - xh, xh * 0.62, sw * 0.9);
      return xh * 0.62;
    }
    return xh * 0.5;
  };

  // ===================== EXPLAINER: "How does AI learn?" =====================
  // One long printed sheet of four panels; the camera tracks along it (Bayer-style info-design spread),
  // then pulls back to show the whole sheet as one diagram for the takeaway.
  let EX_PAPER = null;
  const exPaper = (W, HH) => {
    if (EX_PAPER) return EX_PAPER;
    const cv = H.layer(W, HH), x = cv.getContext('2d'), img = x.createImageData(W, HH), pd = img.data;
    const lo = cachedField('lo', W, HH, 11, 24, 4), fib = cachedField('fib', W, HH, 12, 2, 2, 3.5, 0.5), r0 = H.rng(5);
    const base = H.hex(C.cream), tan = H.hex('#c9ab78');
    for (let y = 0, p = 0; y < HH; y++) for (let xx = 0; xx < W; xx++, p++) {
      const ex = Math.min(xx, W - xx) / W, ey = Math.min(y, HH - y) / HH;
      const edge = Math.pow(1 - H.clamp(Math.min(ex * 3.2, ey * 2.2) + lo[p] * 0.15, 0, 1), 3);
      const k = 0.35 * edge + 0.12 * Math.max(0, lo[p]);
      const s = 1 + fib[p] * 0.035 + (r0() - 0.5) * 0.04, i = p * 4;
      pd[i] = (base[0] + (tan[0] - base[0]) * k) * s; pd[i + 1] = (base[1] + (tan[1] - base[1]) * k) * s; pd[i + 2] = (base[2] + (tan[2] - base[2]) * k) * s; pd[i + 3] = 255;
    }
    x.putImageData(img, 0, 0);
    const rf = H.rng(77);
    for (let i = 0; i < 26; i++) {
      const px = rf.range(0, W), py = rf.range(0, HH), rr = rf.range(2, 10), g = x.createRadialGradient(px, py, 0, px, py, rr);
      g.addColorStop(0, 'rgba(140,90,40,0.22)'); g.addColorStop(1, 'rgba(140,90,40,0)'); x.fillStyle = g; x.beginPath(); x.arc(px, py, rr, 0, 7); x.fill();
    }
    return (EX_PAPER = cv);
  };

  // geometric pictures: cat = yellow card, dog = blue card
  const exCard = (c, kind, x, y, s) => {
    c.save(); c.translate(x, y);
    c.fillStyle = kind === 'cat' ? C.yellow : C.blue; c.fillRect(-s / 2, -s / 2, s, s);
    if (kind === 'cat') {
      c.fillStyle = C.black;
      c.beginPath(); c.moveTo(-s * 0.3, -s * 0.06); c.lineTo(-s * 0.26, -s * 0.38); c.lineTo(-s * 0.06, -s * 0.2); c.closePath(); c.fill();
      c.beginPath(); c.moveTo(s * 0.3, -s * 0.06); c.lineTo(s * 0.26, -s * 0.38); c.lineTo(s * 0.06, -s * 0.2); c.closePath(); c.fill();
      c.beginPath(); c.arc(0, s * 0.06, s * 0.28, 0, 7); c.fill();
      c.fillStyle = C.yellow; c.beginPath(); c.arc(-s * 0.1, s * 0.02, s * 0.05, 0, 7); c.arc(s * 0.1, s * 0.02, s * 0.05, 0, 7); c.fill();
      c.fillStyle = C.red; c.beginPath(); c.moveTo(-s * 0.05, s * 0.12); c.lineTo(s * 0.05, s * 0.12); c.lineTo(0, s * 0.18); c.closePath(); c.fill();
    } else {
      c.fillStyle = C.cream; c.beginPath(); c.arc(0, s * 0.04, s * 0.27, 0, 7); c.fill();
      c.fillStyle = C.black;
      c.beginPath(); c.arc(-s * 0.27, s * 0.0, s * 0.13, -Math.PI / 2, Math.PI / 2, true); c.closePath(); c.fill();
      c.beginPath(); c.arc(s * 0.27, s * 0.0, s * 0.13, -Math.PI / 2, Math.PI / 2); c.closePath(); c.fill();
      c.beginPath(); c.arc(-s * 0.09, -s * 0.01, s * 0.04, 0, 7); c.arc(s * 0.09, -s * 0.01, s * 0.04, 0, 7); c.fill();
      c.beginPath(); c.arc(0, s * 0.12, s * 0.06, 0, 7); c.fill();
    }
    c.restore();
  };
  // label tag that lands on the thing it labels
  const exTag = (c, txt, x, y, p, size = 28, bg = C.black, fg = C.cream) => {
    if (p <= 0) return;
    c.save(); c.font = `700 ${size}px "Space Grotesk"`; c.textBaseline = 'middle';
    const w = c.measureText(txt).width + size * 0.9, h = size * 1.5, dy = -(1 - H.ease.back(p)) * 30;
    c.fillStyle = bg; c.fillRect(x - w / 2, y - h / 2 + dy, w, h);
    c.fillStyle = fg; c.textAlign = 'center'; c.fillText(txt, x, y + dy + 1);
    c.restore();
  };
  // thick Bauhaus arrow (bar + triangle), drawn on with progress p
  const exArrow = (c, x0, y0, x1, y1, p, w = 10, col = C.black) => {
    if (p <= 0) return;
    const L = Math.hypot(x1 - x0, y1 - y0), a = Math.atan2(y1 - y0, x1 - x0), l = L * p;
    c.save(); c.translate(x0, y0); c.rotate(a); c.fillStyle = col;
    c.fillRect(0, -w / 2, Math.max(0, l - w * 2), w);
    c.beginPath(); c.moveTo(l, 0); c.lineTo(l - w * 2.6, -w * 1.5); c.lineTo(l - w * 2.6, w * 1.5); c.closePath(); c.fill();
    c.restore();
  };
  // the model: the robot head from the poster, with three weight dials on a control bar
  const exRobot = (c, x, y, s, dials, look, mood = 0) => {
    const k = s / 300, hx = x - s / 2, hy = y - s / 2;
    c.fillStyle = C.black; c.fillRect(x - 100 * k, hy - 62 * k, 200 * k, 52 * k);
    dials.forEach((a, i) => {
      const dx = x + (i - 1) * 62 * k, dy = hy - 36 * k;
      c.fillStyle = C.cream; c.beginPath(); c.arc(dx, dy, 19 * k, 0, 7); c.fill();
      c.save(); c.translate(dx, dy); c.rotate(a); c.fillStyle = [C.red, C.blue, C.black][i]; c.fillRect(-3 * k, -17 * k, 6 * k, 17 * k); c.restore();
    });
    c.fillStyle = C.red; c.beginPath(); c.arc(hx, y, 50 * k, Math.PI / 2, Math.PI * 1.5); c.closePath(); c.fill();
    c.fillStyle = C.black; c.beginPath(); c.arc(hx + s, y, 50 * k, -Math.PI / 2, Math.PI / 2); c.closePath(); c.fill();
    c.fillStyle = C.blue; c.fillRect(hx, hy, s, s);
    c.fillStyle = C.yellow; c.beginPath(); c.arc(hx + 85 * k, hy + 105 * k, 50 * k, 0, 7); c.fill();
    c.fillStyle = mood > 0 ? C.yellow : C.red; c.fillRect(hx + s - 135 * k, hy + 55 * k, 100 * k, 100 * k);
    const dx = H.lerp(-8, 18, look) * k;
    c.fillStyle = C.black; c.beginPath(); c.arc(hx + 85 * k + dx, hy + 105 * k, 21 * k, 0, 7); c.arc(hx + s - 85 * k + dx, hy + 105 * k, 21 * k, 0, 7); c.fill();
    c.fillStyle = C.yellow; c.beginPath(); c.moveTo(x - 26 * k, hy + 150 * k); c.lineTo(x + 26 * k, hy + 150 * k); c.lineTo(x, hy + 196 * k); c.closePath(); c.fill();
    c.fillStyle = C.black; c.fillRect(x - 92 * k, hy + 220 * k, 184 * k, 46 * k);
    c.fillStyle = C.blue; for (let i = 0; i < 5; i++) c.fillRect(x - 76 * k + i * 33 * k, hy + 228 * k, 13 * k, 30 * k);
  };
  const fmt = (n) => Math.round(n).toLocaleString('en-US');

  // colour separations: every fill lands on its own plate (yellow / red / blue / black) and knocks the same shape out
  // of the other plates, exactly like a litho knockout. Cream fills knock out all plates (reversed type shows paper).
  // The plates are then printed with the per-colour misregistration offsets, overlapping slivers multiply.
  const PLATE_COLS = ['yellow', 'red', 'blue', 'black'];
  const PLATE_OF = { [C.yellow]: 0, [C.red]: 1, [C.blue]: 2, [C.black]: 3 };
  let PLATES = null;
  const plateCtx = (W, HH) => {
    if (!PLATES || PLATES[0].width !== W || PLATES[0].height !== HH) PLATES = PLATE_COLS.map(() => H.layer(W, HH));
    const cs = PLATES.map((pl) => { const x = pl.getContext('2d'); x.setTransform(1, 0, 0, 1, 0, 0); x.globalAlpha = 1; x.globalCompositeOperation = 'source-over'; x.clearRect(0, 0, W, HH); return x; });
    let fill = C.black, stroke = C.black;
    const paint = (style, op) => { const k = style in PLATE_OF ? PLATE_OF[style] : style === C.cream ? -1 : 3;
