      for (let j = 0; j < gh; j++) for (let i = 0; i < gw; i++) {
        const x = gx0 + i * G, y = gy0 + j * G, dx = x - cx, dy = y - cy, r2 = dx * dx + dy * dy, r = Math.sqrt(r2);
