    const CUR = ['#.........', '##........', '#o#.......', '#oo#......', '#ooo#.....', '#oooo#....', '#ooooo#...', '#oooooo#..', '#ooooooo#.', '#oooo#####', '#oo#o#....', '#o#.#o#...', '##..#o#...', '.....#o#..', '.....#o#..', '......##..'];
